function centers(){if(!active)return;const r=active,model=r.library.models[r.config.k],state=model.history[Number($('km-iteration').value)],points=r.library.trainingView.map(p=>{const z=M.scale(p,model.scaler);const ds=state.centers.map(c=>z.reduce((s,v,j)=>s+(v-c[j])**2,0));return{x:z[0],y:z[1],label:ds.indexOf(Math.min(...ds))};});$('km-snapshot').innerHTML=`<p>真实训练快照 ${state.iteration}；SSE=${U.fmt(state.SSE,4)}；训练井抽样散点用于显示，中心和SSE使用全部${r.library.trainRows}有效训练行。</p>`+T.scatter(points,state.centers.map((c,i)=>({x:c[0],y:c[1],name:'中心'+(i+1)})),'标准化相对logROP','标准化扭矩响应')+'<p>这里只回放真实中心状态；主曲线与评价仍使用最终冻结中心，测试点不参与中心拟合。</p>';}
function update(run){active=run;const cal=run.library.cal,points=cal.rows.map(row=>{const x=C.predictors(row);return{x:x[1],y:Math.log(row.ROP_m_h)-cal.beta[2]*x[2]-cal.beta[3]*x[3],label:0};}),xmin=Math.min(...points.map(p=>p.x)),xmax=Math.max(...points.map(p=>p.x));$('calibration-scatter').innerHTML='<h3>独立同响应标定：扣除转速/流量贡献后查看钻压</h3>'+T.scatter(points,[{x:xmin,y:cal.beta[0]+cal.beta[1]*xmin,name:'拟合左端'},{x:xmax,y:cal.beta[0]+cal.beta[1]*xmax,name:'拟合右端'}],'log(WOB / 20kN)','logROP − RPM/流量贡献',null,true)+`<p>160个独立标定观测点；拟合logROP=${cal.beta.map((v,i)=>U.fmt(v,4)+(i?'×x'+i:'')).join(' + ')}；非截距岭惩罚${cal.lambda}。没有用混合地层测试曲线反拟合工况。</p>`;const model=run.library.models[run.config.k];$('km-iteration').max=model.history.length-1;$('km-iteration').value=model.history.length-1;centers();const points2=run.inference.norm.filter(v=>v.valid),labels=points2.map(v=>{const z=M.scale(v.x,model.scaler),ds=model.centers.map(c=>z.reduce((s,v,j)=>s+(v-c[j])**2,0));return ds.indexOf(Math.min(...ds));}),count=a=>a.reduce((n,v,i)=>n+(i===0||v!==a[i-1]?1:0),0),strip=(a,y)=>a.map((v,i)=>`<rect x="${50+i*600/a.length}" y="${y}" width="${600/a.length+.2}" height="28" fill="${T.palette[v]}"/>`).join('');$('segmentation-strips').innerHTML=`<h3>同一批有效深度点：逐点最近中心 → 连续性/最小段长后</h3><svg viewBox="0 0 700 130" role="img" aria-label="原始标签与连续分段对照">${strip(labels,28)}${strip(run.inference.labels,78)}<g font-size="12" fill="#365144"><text x="50" y="20">逐点标签，${count(labels)}段</text><text x="50" y="72">最终连续标签，${count(run.inference.labels)}段</text><text x="50" y="122">1200 → 1280 m MD；无效点排除；颜色对应响应簇1–${run.config.k}</text></g></svg><p>切换惩罚${run.config.penalty}，最小段长${run.config.minLength}个有效点。条带比较不等于地层正确率；薄层是否漏掉仍由独立真值边界表评价。</p>`;}
